// SCORM runtime video config
// Auto-generated by SCORM export
window.SCORM_VIDEO_CONFIG = {"enabled": false, "endpoint": "https://api2.heygen.com/v1/scorm/video_info.get", "draftVideoId": "", "apiKey": ""};

window.fetchScormRuntimeData = window.fetchScormRuntimeData || function() {
  var cfg = window.SCORM_VIDEO_CONFIG || {};
  if (!cfg.enabled || !cfg.endpoint || !cfg.draftVideoId || !cfg.apiKey) {
    window.__SCORM_RUNTIME_FETCH_PROMISE = Promise.resolve(false);
    return window.__SCORM_RUNTIME_FETCH_PROMISE;
  }
  if (
    window.__SCORM_RUNTIME_FETCH_PROMISE &&
    window.__SCORM_RUNTIME_FETCH_DRAFT_ID === cfg.draftVideoId
  ) {
    return window.__SCORM_RUNTIME_FETCH_PROMISE;
  }

  var url =
    cfg.endpoint +
    "?draft_video_id=" +
    encodeURIComponent(cfg.draftVideoId) +
    "&_ts=" +
    Date.now();
  window.__SCORM_RUNTIME_FETCH_PROMISE = fetch(url, {
    method: "GET",
    cache: "no-store",
    headers: {
      "x-api-key": cfg.apiKey
    }
  })
    .then(function(resp) { return resp.json(); })
    .then(function(payload) {
      if (!payload || payload.code !== 100 || !payload.data) return false;
      var data = payload.data;

      // Keep <video src> and <source src> identical. If only <source> is updated, browsers
      // still play <video src> when it is set — packaged SCORM + heygenScormWrapper.init both
      // assign video.src, so runtime refresh must overwrite both.
      var applyVideoUrlToVideoElement = function(videoUrl, force) {
        if (!videoUrl) return;
        var sourceNode = document.getElementById("videoSource");
        var videoNode = document.getElementById("miVideo");
        if (!videoNode) return;

        var next = String(videoUrl);
        if (!force) {
          var currentVideo = (videoNode.currentSrc || videoNode.src || "").split("#")[0];
          var currentSource = sourceNode ? (sourceNode.src || "").split("#")[0] : "";
          if (currentVideo === next && (!sourceNode || currentSource === next)) return;
        }

        videoNode.src = next;
        if (sourceNode) {
          sourceNode.src = next;
        }
        if (typeof videoNode.load === "function") videoNode.load();
      };

      var applyVideoSourceFromLanguageConfig = function() {
        var sourceNode = document.getElementById("videoSource");
        var videoNode = document.getElementById("miVideo");
        if (!videoNode || !window.LANGUAGE_CONFIG || !Array.isArray(window.LANGUAGE_CONFIG.languages)) return;

        var selectedCode = null;
        var languageSelect = document.getElementById("languageSelect");
        if (languageSelect && languageSelect.selectedIndex >= 0 && languageSelect.options[languageSelect.selectedIndex]) {
          selectedCode = languageSelect.options[languageSelect.selectedIndex].getAttribute("data-lang-code");
        }
        if (!selectedCode && window.LANGUAGE_CONFIG.defaultLanguage) selectedCode = window.LANGUAGE_CONFIG.defaultLanguage;

        var selectedEntry = window.LANGUAGE_CONFIG.languages.find(function(lang) {
          return lang.code === selectedCode;
        });
        if (!selectedEntry && window.LANGUAGE_CONFIG.languages.length > 0) {
          selectedEntry = window.LANGUAGE_CONFIG.languages[0];
        }
        if (!selectedEntry || !selectedEntry.videoFile) return;

        var vf = String(selectedEntry.videoFile);
        var cur = (videoNode.currentSrc || videoNode.src || "").split("#")[0];
        if (cur === vf && (!sourceNode || (sourceNode.src || "").split("#")[0] === vf)) return;

        videoNode.src = vf;
        if (sourceNode) {
          sourceNode.src = vf;
        }
        if (typeof videoNode.load === "function") videoNode.load();
      };

      var syncLanguageSelectorFromConfig = function() {
        var selectElement = document.getElementById("languageSelect");
        if (!selectElement || !window.LANGUAGE_CONFIG || !Array.isArray(window.LANGUAGE_CONFIG.languages)) return;

        var selectedCode = null;
        if (selectElement.selectedIndex >= 0 && selectElement.options[selectElement.selectedIndex]) {
          selectedCode = selectElement.options[selectElement.selectedIndex].getAttribute("data-lang-code");
        }
        if (!selectedCode && window.LANGUAGE_CONFIG.defaultLanguage) {
          selectedCode = window.LANGUAGE_CONFIG.defaultLanguage;
        }

        selectElement.innerHTML = "";
        window.LANGUAGE_CONFIG.languages.forEach(function(lang) {
          var option = document.createElement("option");
          option.value = lang.videoFile;
          option.textContent = lang.label;
          option.setAttribute("data-lang-code", lang.code);
          selectElement.appendChild(option);
        });

        if (selectedCode) {
          for (var i = 0; i < selectElement.options.length; i++) {
            if (selectElement.options[i].getAttribute("data-lang-code") === selectedCode) {
              selectElement.selectedIndex = i;
              break;
            }
          }
        }
      };

      var map = data.video_url_by_language_code || data.video_urls_by_language_code || data.video_urls;

      var hasApiUrls =
        !!data.video_url || (map && typeof map === "object" && Object.keys(map).length > 0);

      var resolveMapUrlForLang = function(langCode) {
        if (!map || typeof map !== "object") return "";
        if (langCode != null && map[langCode] != null && String(map[langCode]) !== "") {
          return String(map[langCode]);
        }
        var want = String(langCode || "").toLowerCase();
        for (var k in map) {
          if (!Object.prototype.hasOwnProperty.call(map, k)) continue;
          if (String(k).toLowerCase() === want && map[k] != null && String(map[k]) !== "") {
            return String(map[k]);
          }
        }
        return "";
      };

      // Successful API response is the source of truth for playback URLs: overwrite packaged
      // LANGUAGE_CONFIG[].videoFile from the API (per-code map, then default video_url, then map.default).
      if (window.LANGUAGE_CONFIG && Array.isArray(window.LANGUAGE_CONFIG.languages)) {
        if (hasApiUrls) {
          window.LANGUAGE_CONFIG.languages.forEach(function(lang) {
            if (!lang) return;
            var u =
              resolveMapUrlForLang(lang.code) ||
              (data.video_url ? String(data.video_url) : "") ||
              resolveMapUrlForLang("default") ||
              (map && map.default != null ? String(map.default) : "") ||
              "";
            if (u) {
              lang.videoFile = u;
            }
          });
          syncLanguageSelectorFromConfig();
        }
      }

      // Prefer the URL for the currently selected language (multi-track) so playback matches API per-lang data.
      var primaryPlaybackUrl = "";
      if (window.LANGUAGE_CONFIG && Array.isArray(window.LANGUAGE_CONFIG.languages) && window.LANGUAGE_CONFIG.languages.length > 0) {
        var ls = document.getElementById("languageSelect");
        var selCode = null;
        if (ls && ls.selectedIndex >= 0 && ls.options[ls.selectedIndex]) {
          selCode = ls.options[ls.selectedIndex].getAttribute("data-lang-code");
        }
        if (!selCode && window.LANGUAGE_CONFIG.defaultLanguage) {
          selCode = window.LANGUAGE_CONFIG.defaultLanguage;
        }
        var selEntry = window.LANGUAGE_CONFIG.languages.find(function(l) {
          return l && l.code === selCode;
        });
        if (!selEntry) {
          selEntry = window.LANGUAGE_CONFIG.languages[0];
        }
        if (selEntry && selEntry.videoFile) {
          primaryPlaybackUrl = String(selEntry.videoFile);
        }
      }
      if (!primaryPlaybackUrl) {
        primaryPlaybackUrl =
          data.video_url || (map && typeof map === "object" && map.default ? String(map.default) : "") || "";
      }
      if (primaryPlaybackUrl) {
        window.__SCORM_RUNTIME_VIDEO_URL = primaryPlaybackUrl;
        applyVideoUrlToVideoElement(primaryPlaybackUrl, hasApiUrls);
      }
      // Only sync from LANGUAGE_CONFIG when the API merged URLs into it. Otherwise this
      // overwrites a fresh primaryPlaybackUrl with stale packaged LANGUAGE_CONFIG (video.src
      // vs #videoSource mismatch and wrong playback).
      if (hasApiUrls) {
        applyVideoSourceFromLanguageConfig();
      }

      var interactiveVideo = data.interactive_video || {};
      var draftData = interactiveVideo.draft_data || data.draft_data;
      if (draftData) {
        window.DRAFT_DATA = draftData;
      }

      var segmentMetadata = Array.isArray(interactiveVideo.segment_metadata)
        ? interactiveVideo.segment_metadata
        : data.segment_metadata;
      if (Array.isArray(segmentMetadata) && segmentMetadata.length > 0) {
        window.SEGMENT_METADATA = segmentMetadata.map(function(seg) {
          return {
            segmentId: seg.segment_id || seg.segmentId || "default",
            videoId: seg.video_id || seg.videoId || data.draft_video_id || "",
            sceneIds: seg.scene_ids || seg.sceneIds || [],
            videoUrl: seg.video_url || seg.videoUrl || "",
            nextSceneId: seg.next_scene_id || seg.nextSceneId || null
          };
        });
      } else if (hasApiUrls && primaryPlaybackUrl) {
        var packagedSegs = window.SEGMENT_METADATA;
        if (packagedSegs && Array.isArray(packagedSegs) && packagedSegs.length > 0) {
          window.SEGMENT_METADATA = packagedSegs.map(function(seg) {
            if (!seg) return seg;
            var next = {};
            for (var key in seg) {
              if (Object.prototype.hasOwnProperty.call(seg, key)) {
                next[key] = seg[key];
              }
            }
            next.videoUrl = primaryPlaybackUrl;
            return next;
          });
        } else {
          var draftForSeg = window.DRAFT_DATA;
          var sceneIdsFromDraft = [];
          if (
            draftForSeg &&
            draftForSeg.text_draft &&
            draftForSeg.text_draft.visual &&
            Array.isArray(draftForSeg.text_draft.visual.layout)
          ) {
            sceneIdsFromDraft = draftForSeg.text_draft.visual.layout.slice();
          }
          window.SEGMENT_METADATA = [
            {
              segmentId: "default_segment",
              videoId: data.draft_video_id != null ? String(data.draft_video_id) : "",
              sceneIds: sceneIdsFromDraft,
              videoUrl: primaryPlaybackUrl,
              nextSceneId: null
            }
          ];
        }
      }
      return true;
    })
    .catch(function(err) {
      console.warn("[SCORM API] runtime fetch failed, using packaged data", err);
      return false;
    });
  window.__SCORM_RUNTIME_FETCH_DRAFT_ID = cfg.draftVideoId;
  return window.__SCORM_RUNTIME_FETCH_PROMISE;
};
